/**
 * Generated by: adlc-framework/.claude/plugins/commerce/scripts/autotest.sh
 * Flow: quote-negotiate
 * Scope: commerce-autonomous-test-authoring
 *
 * DETERMINISTIC SPEC — no LLM/MCP/agent imports. Plain Playwright.
 *
 * Flow: buyer requests quote → admin navigates to quotes → buyer views quote
 *       assert quote details page renders with quote ID visible
 */

import path from "node:path";
import { test, expect } from "../fixtures/auth";
import {
  STOREFRONT_URL,
  BACKEND_URL,
  SCREENSHOTS_DIR,
  TEST_REGION_COUNTRY,
  QUOTE_FEATURE_ENABLED,
} from "../config";

test.describe("B2B quote-negotiate flow [generated]", () => {
  test("buyer creates quote and buyer navigates to quote details", async ({
    buyerPage,
  }) => {
    if (!QUOTE_FEATURE_ENABLED) {
      test.skip(true, "QUOTE_FEATURE_ENABLED=false — skipping quote-negotiate");
      return;
    }

    // Step 1: navigate to cart
    await buyerPage.goto(`${STOREFRONT_URL}/${TEST_REGION_COUNTRY}/cart`);
    await buyerPage.waitForLoadState("networkidle");

    await buyerPage.screenshot({
      path: path.join(SCREENSHOTS_DIR, "generated-quote-negotiate-01-cart.png"),
    });

    // Step 2: click "Request Quote"
    const requestQuoteBtn = buyerPage.getByRole("button", { name: "Request Quote" }).first();
    await expect(requestQuoteBtn).toBeVisible({ timeout: 5000 });
    await requestQuoteBtn.click();
    await buyerPage.waitForLoadState("networkidle");

    await buyerPage.screenshot({
      path: path.join(SCREENSHOTS_DIR, "generated-quote-negotiate-02-quote-modal.png"),
    });

    // Step 3: submit quote form (find Submit button and click)
    const buttons = await buyerPage.locator('[role="dialog"] button').all();
    let submitted = false;
    for (const btn of buttons) {
      const text = await btn.textContent();
      if (text && text.toLowerCase().trim() === "submit") {
        await btn.click();
        submitted = true;
        break;
      }
    }

    if (!submitted && buttons.length > 1) {
      await buttons[buttons.length - 1].click();
    }

    await buyerPage.waitForLoadState("networkidle", { timeout: 15000 });
    await buyerPage.waitForTimeout(2000);

    await buyerPage.screenshot({
      path: path.join(SCREENSHOTS_DIR, "generated-quote-negotiate-03-quote-submitted.png"),
    });

    // Step 4: HARD assertion — navigate to /account/quotes (quote details page)
    await buyerPage.goto(`${STOREFRONT_URL}/${TEST_REGION_COUNTRY}/account/quotes`);
    await buyerPage.waitForLoadState("networkidle");

    const quotesPageContent = buyerPage.locator('text=/Quotes|quotes|quote/i').first();
    await expect(quotesPageContent).toBeVisible({ timeout: 5000 });
    console.log("[quote-negotiate] CONTENT CHECK: Quotes page visible");

    await buyerPage.screenshot({
      path: path.join(SCREENSHOTS_DIR, "generated-quote-negotiate-04-quotes-list.png"),
    });

    // Step 5: HARD assertion — click first quote to view details (if row visible)
    const firstQuoteRow = buyerPage.locator('[data-testid="quote-row"]').first()
      .or(buyerPage.locator('table tbody tr').first());

    const isQuoteRowVisible = await firstQuoteRow.isVisible({ timeout: 3000 }).catch(() => false);

    if (isQuoteRowVisible) {
      await firstQuoteRow.locator('a, button').first().click().catch(() => {
        return firstQuoteRow.click();
      });

      await buyerPage.waitForLoadState("networkidle");
      await buyerPage.screenshot({
        path: path.join(SCREENSHOTS_DIR, "generated-quote-negotiate-05-quote-details.png"),
      });

      // Assert quote details page renders
      const quoteDetailsContent = buyerPage.locator('text=/Quote ID|Total|Date/i').first();
      await expect(quoteDetailsContent).toBeVisible({ timeout: 5000 });
      console.log("[quote-negotiate] CONTENT CHECK: Quote details visible");
    }

    console.log("[quote-negotiate] Flow complete");
  });
});
